return $input.all().map(({json}, index) => {
  const {symbol, ticks, completeThroughMs} = json;
  if (symbol !== "XAU/USD" || !Array.isArray(ticks) || !Number.isSafeInteger(completeThroughMs) || completeThroughMs < 0) {
    throw new Error("Expected XAU/USD ticks and a verified completeness timestamp");
  }
  const ordered = ticks.map((tick, sequence) => {
    const {timestampMs, price} = tick ?? {};
    if (!Number.isSafeInteger(timestampMs) || timestampMs < 0 || timestampMs >= 8640000000000000 - 60000 ||
        !Number.isFinite(price) || price <= 0) throw new Error("Invalid price tick");
    return {timestampMs, price, sequence};
  }).sort((a,b) => a.timestampMs-b.timestampMs || a.sequence-b.sequence);
  const bars = new Map();
  for (const {timestampMs, price} of ordered) {
    const minute = Math.floor(timestampMs / 60000) * 60000;
    const bar = bars.get(minute);
    if (bar) {
      bar.high = Math.max(bar.high, price);
      bar.low = Math.min(bar.low, price);
      bar.close = price;
    } else {
      bars.set(minute, {
        openTime: new Date(minute).toISOString(),
        closeTime: new Date(minute + 60000).toISOString(),
        open: price, high: price, low: price, close: price,
      });
    }
  }
  const closed = [], provisional = [];
  for (const [minute, bar] of bars) {
    (minute + 60000 <= completeThroughMs ? closed : provisional).push(bar);
  }
  return {json:{symbol:"XAUUSD", timeframe:"M1", completeThroughMs, closed, provisional},pairedItem:{item:index}};
});
